class Solution:
    def largestWordCount(self, messages: List[str], senders: List[str]) -> str:
        cnt = {}
        for m, s in zip(messages, senders):
            cnt[s] = cnt.get(s, 0) + m.count(' ') + 1
        return max(cnt, key=lambda s: (cnt[s], s))

