class Solution {
    public String largestWordCount(String[] messages, String[] senders) {
        Map<String, Integer> cnt = new HashMap<>();
        for (int i = 0; i < messages.length; i++)
            cnt.merge(senders[i], messages[i].split(" ").length, Integer::sum);
        String best = "";
        int bc = -1;
        for (Map.Entry<String, Integer> e : cnt.entrySet())
            if (e.getValue() > bc || (e.getValue() == bc && e.getKey().compareTo(best) > 0)) {
                bc = e.getValue();
                best = e.getKey();
            }
        return best;
    }
}

